// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue } from '@skyramp/skyramp';
import { create_webhook, get_webhooks_list } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const webhooksPostRequestBody: string = `{
        "collections": [
            "articles"
        ],
        "method": "POST",
        "url": "https://example.com/hooks/created"
    }`;

    const webhooksPostResponse = await create_webhook(client, headers, webhooksPostRequestBody, 201);

    expect(getValue(webhooksPostResponse, "data"), 'created webhook primary key').not.toBeNull();

    const webhooksGetResponse = await get_webhooks_list(client, headers, 200);

    const webhooksList = getValue(webhooksGetResponse, "data");
    expect(Array.isArray(webhooksList), 'data is an array').toBe(true);
    const createdWebhook = webhooksList.find((webhook: any) => webhook.url === "https://example.com/hooks/created");
    expect(createdWebhook, 'created webhook is present in the list').toBeDefined();
    expect(String(createdWebhook.id), 'listed id matches the id returned by POST').toBe(String(getValue(webhooksPostResponse, "data")));
    expect(createdWebhook.url, 'url').toBe("https://example.com/hooks/created");
    expect(createdWebhook.method, 'method').toBe("POST");
    expect(createdWebhook.collections, 'collections').toEqual(["articles"]);
});
